from pathlib import Path
import re, json

work = Path('/workspace/work')
speech = (work / 'speech_draft.md').read_text()
parts = {int(n): [title, body.strip()] for n, title, body in re.findall(r'^# (\d+)\. ([^\n]+)\n\n(.*?)(?=^# |\Z)', speech, re.M | re.S)}

parts[4] = ['Перед поиском — вопрос', '''Вернёмся к учебному обращению. У нас есть внешний адрес, но нам нужно выяснить несколько разных вещей. Замечали ли с него нежелательную активность? Какая программа обращалась к нему? Кто разрешил эту программу запустить? На последний вопрос внешний сервис вообще не сможет ответить.

Выберем объект под каждый вопрос. Для истории IP подойдёт AbuseIPDB. Для конкретного файла нужен его хеш, лучше SHA-256: отпечаток именно этих байтов. По нему можно искать готовый отчёт VirusTotal. Имя файла такой точности не даёт: его легко изменить.

Если в письме была ссылка, различаем полный URL и домен. URL включает конкретный путь и иногда параметры. Отчёт о домене не описывает автоматически каждую его страницу. Сохраняем исходную ссылку внутри расследования, а перед внешним запросом отдельно проверяем, что допустимо раскрыть.

Запишем вопрос до открытия вкладки: «Что известно об этом объекте и как это поможет проверить событие?» Так мы получим понятную задачу для каждого источника. Начнём с истории сообщений об IP.''']

parts[5] = ['AbuseIPDB: история сообщений и время', '''AbuseIPDB собирает сообщения о нежелательной активности с сетевых адресов. Читаем даты, период, источники и категории. Сколько пользователей сообщало об адресе? Есть ли содержательные комментарии? Речь о переборе паролей, нежелательной почте или сканировании?

Количество сообщений не равно количеству атак. Повторы могут поступать от одного участника, а разные пользователи не обязательно представляют независимые организации. В API количество сообщений относится к выбранному окну. В интерфейсе записываем тот период, который действительно показан.

Если жалобы касаются сканирования, они помогают понять историю адреса. Они ещё не подтверждают, что именно с него управляли компьютером сотрудника. Отсутствие жалоб означает отсутствие видимых сообщений в этом периоде. Новая или мало наблюдаемая активность могла не попасть в базу.

Оценка уверенности сервиса учитывает сообщения и их возраст. Её нельзя превращать в вероятность нашего инцидента. Даже максимум шкалы не доказывает, что любое соединение с адресом является атакой.

Время особенно важно. Система DNS сопоставляет имя домена с адресом сервера. Сегодняшний ответ может отличаться от ответа в момент события. Сам IP мог перейти другому арендатору; на общем хостинге размещаются разные сайты.

Поэтому историческую связь проверяем по собственным записям или сведениям с понятным временем наблюдения. Название провайдера и страна помогают описать объект, но не определяют намерения пользователя. Проверяем эти детали там, где они меняют вывод.

Полезная заметка: «За такой-то период есть сообщения таких-то типов; отношение к нашему событию ещё проверяется». Теперь перейдём от истории адреса к сведениям о других объектах.''']

parts[5][1] = parts[5][1].replace('В API количество сообщений', 'В программном интерфейсе сервиса — API — количество сообщений')
parts[8][1] = parts[8][1].replace('В отчёте VirusTotal проверяем тип объекта', 'В VirusTotal перейдём к домену maaays[.]xyz из того же отчёта Sygnia. Проверяем тип объекта')
parts[9][1] = parts[9][1].replace('Callback phishing здесь означает фишинг, при котором жертву побуждают позвонить.', 'Фишинг — обман под видом доверенного отправителя или службы. Вариант callback phishing побуждает жертву позвонить.')
parts[10][1] = parts[10][1].replace('в разделе Exfiltration Server.', 'с ролью Exfiltration Server — сервер для выноса данных.')
parts[3][1] = parts[3][1].replace('Мы задаём гипотезу и ищем её следы в доступной истории событий.', 'Мы задаём гипотезу и ищем её следы в доступной истории событий, даже если отдельного предупреждения о них не было.')
parts[11][1] = parts[11][1].replace('Журналы самого сервиса поддержки могут уточнить сеанс и участника.', 'Журналы самого сервиса поддержки могут уточнить сеанс и участника. Сопоставляем записи по устройству, времени, пользователю и идентификатору процесса или сеанса, если он доступен. Спрашиваем: какая программа установила соединение и есть ли следы передачи файлов? Запрос DNS ещё не означает соединение, а исходящий трафик сам по себе не доказывает кражу данных.')
parts[11][1] = parts[11][1].replace('Если события собраны в общей системе поиска, её часто называют SIEM. Это облегчает сопоставление, но не делает данные полными автоматически. Нужно знать охват, срок хранения и точность времени.', 'Если события собраны в общей системе поиска — SIEM, — сопоставлять их удобнее. Полнота всё равно зависит от охвата и срока хранения.')
parts[13][1] = parts[13][1].replace('Теперь вернёмся к событию, с которого начали, и проверим, что изменилось в нашем подходе.', 'Первый конкретный шаг: запросить список запусков средств удалённой поддержки на рабочих станциях за доступные четырнадцать дней. По кандидатам проверить согласование и последующие действия. Теперь вернёмся к началу.')

counts = {n: len(body.split()) for n, (title, body) in parts.items()}
assert len(parts) == 14
non_demo = sum(c for n, c in counts.items() if n != 8)
rate = non_demo / (1350 / 60)
# 100 seconds demonstration, 50 seconds short pauses and transitions.
extras = {1: 10, 2: 3, 3: 3, 4: 3, 5: 3, 6: 10, 7: 3, 9: 3, 10: 3, 11: 3, 12: 3, 13: 3}
# Allocate rounded durations, then give remainder to final slide.
dur = {n: (100 if n == 8 else round((c / rate * 60 + extras.get(n, 0)) / 5) * 5) for n, c in counts.items()}
dur[14] += 1500 - sum(dur.values())
def clock(s):
    return f'{s//60:02}:{s%60:02}'
cursor = 0
times = {}
for n in range(1, 15):
    times[n] = f'{clock(cursor)}–{clock(cursor + dur[n])}'
    cursor += dur[n]
assert cursor == 1500

sources = {5:'R6–R7',6:'R8–R10, R12',7:'R11',8:'R1; результаты карточек не получены',9:'R1–R2',10:'R1, R9'}
blocks = ['## 4. Полный текст устного выступления',
          f'Произносимая часть: {sum(counts.values())} слов, из них {counts[8]} — реплики демонстрации. Для плана заложены около {rate:.0f} слов в минуту вне демонстрации, 1:40 на демонстрацию и короткие паузы. Это репетиционная оценка, а не измеренная длительность. Заголовки, тайминг и редакторские примечания не произносятся.']
for n in range(1,15):
    title, body = parts[n]
    blocks.append(f'### Слайд {n}. {title} • {times[n]}\n\n{body}')
    if n in sources:
        blocks.append(f'*Редакторское основание, не произносить: {sources[n]}; ссылки в разделе 9.*')

brief = (work/'brief.md').read_text().replace('собственная учебная синтеза', 'собственный учебный синтез')
brief = brief.replace('Учебное обращение сотрудника после письма о подписке и звонка;', 'Учебное обращение: сотрудник сам позвонил по номеру из счёта о подписке;')
brief = brief.replace('Сотрудник сообщил о запуске удаленной поддержки после подозрительного письма.', 'Сотрудник сообщил: после письма он сам позвонил по номеру из счёта и запустил удалённую поддержку.')
slides = (work/'slides.md').read_text().replace('IoC — наблюдение с контекстом', 'IoC — признак с контекстом и основанием')
slides = slides.replace('объяснить EDR и DNS одним предложением', 'кратко объяснить EDR; DNS уже введён ранее')
slides = re.sub(r'(### (\d+)\.[^\n]+ • )\d{2}:\d{2}–\d{2}:\d{2}', lambda m: m.group(1)+times[int(m.group(2))], slides)
new_table = '| Время | Слайды | Задача блока |\n| --- | --- | --- |\n'
groups = [(1,2,'Учебное событие; наблюдаемый объект и IoC.'),(3,4,'Роль внешних данных; вопрос, который определяет поиск.'),(5,6,'AbuseIPDB и VirusTotal: чтение результата, время и пределы выводов.'),(7,7,'Готовый отчет, новый анализ и раскрытие данных.'),(8,8,'Необязательная демонстрация либо запасной экранный разбор.'),(9,10,'Реальный Luna Moth; один исторический переход и пределы атрибуции.'),(11,12,'Возвращение в учебную инфраструктуру, проверка и запись вывода.'),(13,14,'Проверяемая гипотеза hunting; алгоритм и возврат к началу.')]
for a,b,label in groups:
    timing = times[a].split('–')[0]+'–'+times[b].split('–')[1]
    new_table += f'| {timing} | {a if a==b else str(a)+"–"+str(b)} | {label} |\n'
brief = re.sub(r'\| Время \| Слайды \| Задача блока \|.*?(?=\n\nВопросы аудитории)',new_table.rstrip(),brief,flags=re.S)
brief = brief.replace('<!-- SPEECH -->','\n\n'.join(blocks))
brief = brief.replace('<!-- SLIDES -->',slides)
brief = brief.replace('Проверить отметки 06:10, 12:10, 17:10 и 20:50.', f'Проверить отметки {times[5].split("–")[0]}, {times[8].split("–")[0]}, {times[11].split("–")[0]} и {times[13].split("–")[0]}.')
(work/'ti_talk_full.md').write_text(brief)
(work/'speech_final.md').write_text('\n\n'.join(blocks))
(work/'timing.json').write_text(json.dumps({'speech_words':sum(counts.values()),'demo_words':counts[8],'target_rate':rate,'counts':counts,'times':times,'durations_seconds':dur},ensure_ascii=False,indent=2))
print(json.dumps({'speech_words':sum(counts.values()),'demo_words':counts[8],'target_rate':round(rate,1),'times':times},ensure_ascii=False))
